create or replace function private.normalize_e164_phone(p_phone text) returns text language plpgsql immutable set search_path = pg_catalog as $$ declare v_digits text; begin v_digits := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'); if v_digits = '' then return null; end if; if left(v_digits, 2) = '00' then v_digits := substr(v_digits, 3); end if; if length(v_digits) = 10 and left(v_digits, 1) = '0' then v_digits := substr(v_digits, 2); end if; if length(v_digits) = 9 then v_digits := '244' || v_digits; end if; if length(v_digits) < 8 or length(v_digits) > 15 then return null; end if; return '+' || v_digits; end; $$;